import assert from 'node:assert/strict';import path from'node:path';import{readFile,writeFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{applyComponents}from'../../scripts/component-export.mjs';
const artifact=path.resolve('artifacts/platform/events-heldout'),route='/events/month/2028-03/',generated=process.argv.includes('--generated');let server,browser;const results=[];
try{server=await serveStatic(path.join(artifact,'project/output'));browser=await chromium.launch({channel:'chrome'});
 for(const [kind,origin]of [['source','http://127.0.0.1:9440'],['export',server.url]]){const page=await browser.newPage({viewport:{width:1440,height:900}});if(kind==='export'&&!generated)await page.route(server.url+route,async r=>{const $=load(await readFile(path.join(artifact,'project/output',route,'index.html'),'utf8'));applyComponents($);await r.fulfill({contentType:'text/html',body:$.html()});});await page.goto(origin+route,{waitUntil:'networkidle'});const trigger=page.locator('[data-js~="tribe-events-tooltip"]:visible').first();await trigger.hover();const tooltip=page.locator('.tooltipster-base:visible');await tooltip.waitFor();const bounds=await tooltip.boundingBox(),text=(await tooltip.innerText()).replace(/\s+/g,' ').trim();await tooltip.screenshot({path:path.join(artifact,'tooltip-'+kind+'.png')});await trigger.focus();await page.mouse.move(5,5);await page.keyboard.press('Escape');await tooltip.waitFor({state:'hidden'});let dynamicEmptyMonth=false;if(kind==='export'&&generated){await page.goto(origin+'/events/month/?calendar-date=2028-03-01',{waitUntil:'networkidle'});const dynamic=page.locator('[data-js~="tribe-events-tooltip"]:visible').first();await dynamic.hover();await page.locator('[data-cloner-tooltip]').waitFor();assert.equal((await page.locator('[data-cloner-tooltip]').innerText()).replace(/\s+/g,' ').trim(),text);const ids=await page.locator('[id]').evaluateAll(es=>es.map(e=>e.id));assert.equal(new Set(ids).size,ids.length);dynamicEmptyMonth=true;}results.push({kind,bounds,text,escapeDismisses:true,dynamicEmptyMonth});await page.close();}
 for(const dimension of ['x','y','width','height'])assert.ok(Math.abs(results[0].bounds[dimension]-results[1].bounds[dimension])<0.01,dimension+' differs');assert.equal(results[0].text,results[1].text);await writeFile(path.join(artifact,generated?'tooltip-generated-check.json':'tooltip-candidate-check.json'),JSON.stringify({scope:'Installed desktop tooltip contents, size and Escape behavior; not complete interaction parity',results},null,2));console.log(JSON.stringify({results}));
}finally{await browser?.close();await server?.close();}
